import { component$, Slot, useSignal, useStore, useContextProvider, createContextId, Signal } from "@builder.io/qwik";

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

export interface CartStore {
  items: CartItem[];
}

export type ThemeValue = "light" | "dark";

export const ThemeContext = createContextId<Signal<ThemeValue>>("theme-context");
export const CartContext = createContextId<CartStore>("cart-context");

export default component$(() => {
  const theme = useSignal<ThemeValue>("light");
  const cart = useStore<CartStore>({
    items: [
      { id: "sku-1", name: "Keyboard", price: 49.99, quantity: 1 },
      { id: "sku-2", name: "Mouse", price: 19.99, quantity: 2 }
    ]
  }, { deep: true });

  useContextProvider(ThemeContext, theme);
  useContextProvider(CartContext, cart);

  return <Slot />;
});

import { component$, useContext, useComputed$ } from "@builder.io/qwik";
import { ThemeContext, CartContext } from "./layout";

export const Level3 = component$(() => {
  const theme = useContext(ThemeContext);
  const cart = useContext(CartContext);

  const aggregates = useComputed$(() => {
    let count = 0;
    let total = 0;
    for (const item of cart.items) {
      count += item.quantity;
      total += item.price * item.quantity;
    }
    return {
      count,
      total: `$${total.toFixed(2)}`
    };
  });

  return (
    <div data-testid="app-root" data-theme={theme.value}>
      <h1 data-testid="theme-label">Theme: {theme.value}</h1>
      <button
        data-testid="theme-toggle"
        onClick$={() => {
          theme.value = theme.value === "light" ? "dark" : "light";
        }}
      >
        Toggle Theme
      </button>

      <div>
        <h2>Cart</h2>
        <div>
          Total Items: <span data-testid="cart-count">{aggregates.value.count}</span>
        </div>
        <div>
          Total Price: <span data-testid="cart-total">{aggregates.value.total}</span>
        </div>

        <button
          data-testid="add-item"
          onClick$={() => {
            const exists = cart.items.some(item => item.id === "sku-3");
            if (!exists) {
              cart.items.push({
                id: "sku-3",
                name: "Cable",
                price: 9.99,
                quantity: 1
              });
            }
          }}
        >
          Add Cable
        </button>

        <div>
          {cart.items.map((item) => (
            <div key={item.id} data-testid={`item-${item.id}`}>
              <span>{item.name}</span>
              <span> - Qty: </span>
              <span data-testid={`qty-${item.id}`}>{item.quantity}</span>
              <button
                data-testid={`inc-${item.id}`}
                onClick$={() => {
                  item.quantity++;
                }}
              >
                +
              </button>
              <button
                data-testid={`dec-${item.id}`}
                onClick$={() => {
                  if (item.quantity > 0) {
                    item.quantity--;
                  }
                }}
              >
                -
              </button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
});

export const Level2 = component$(() => {
  return <Level3 />;
});

export const Level1 = component$(() => {
  return <Level2 />;
});

export default component$(() => {
  return <Level1 />;
});

import { chromium } from "playwright";

async function run() {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  console.log("Navigating to http://localhost:3000/ ...");
  await page.goto("http://localhost:3000/");

  // 1. Check app-root and initial theme
  const appRoot = await page.locator('[data-testid="app-root"]');
  const initialTheme = await appRoot.getAttribute("data-theme");
  console.log("Initial theme attribute:", initialTheme);
  if (initialTheme !== "light") {
    throw new Error(`Expected initial theme to be "light", got "${initialTheme}"`);
  }

  // 2. Check theme-label
  const themeLabel = await page.locator('[data-testid="theme-label"]').innerText();
  console.log("Theme label:", themeLabel);
  if (themeLabel !== "Theme: light") {
    throw new Error(`Expected theme label to be "Theme: light", got "${themeLabel}"`);
  }

  // 3. Check cart-count and cart-total
  const cartCount = await page.locator('[data-testid="cart-count"]').innerText();
  console.log("Cart count:", cartCount);
  if (cartCount !== "3") {
    throw new Error(`Expected cart count to be "3", got "${cartCount}"`);
  }

  const cartTotal = await page.locator('[data-testid="cart-total"]').innerText();
  console.log("Cart total:", cartTotal);
  if (cartTotal !== "$89.97") {
    throw new Error(`Expected cart total to be "$89.97", got "${cartTotal}"`);
  }

  // 4. Check initial items
  const item1Qty = await page.locator('[data-testid="qty-sku-1"]').innerText();
  console.log("sku-1 quantity:", item1Qty);
  if (item1Qty !== "1") {
    throw new Error(`Expected sku-1 quantity to be "1", got "${item1Qty}"`);
  }

  const item2Qty = await page.locator('[data-testid="qty-sku-2"]').innerText();
  console.log("sku-2 quantity:", item2Qty);
  if (item2Qty !== "2") {
    throw new Error(`Expected sku-2 quantity to be "2", got "${item2Qty}"`);
  }

  // 5. Toggle theme
  console.log("Clicking theme-toggle...");
  await page.locator('[data-testid="theme-toggle"]').click();

  // Wait to ensure state updates
  await page.waitForTimeout(500);

  const updatedTheme = await appRoot.getAttribute("data-theme");
  console.log("Updated theme attribute:", updatedTheme);
  if (updatedTheme !== "dark") {
    throw new Error(`Expected updated theme to be "dark", got "${updatedTheme}"`);
  }

  const updatedThemeLabel = await page.locator('[data-testid="theme-label"]').innerText();
  console.log("Updated theme label:", updatedThemeLabel);
  if (updatedThemeLabel !== "Theme: dark") {
    throw new Error(`Expected updated theme label to be "Theme: dark", got "${updatedThemeLabel}"`);
  }

  // 6. Increment sku-1
  console.log("Incrementing sku-1...");
  await page.locator('[data-testid="inc-sku-1"]').click();
  await page.waitForTimeout(500);

  const item1QtyNew = await page.locator('[data-testid="qty-sku-1"]').innerText();
  console.log("sku-1 quantity after inc:", item1QtyNew);
  if (item1QtyNew !== "2") {
    throw new Error(`Expected sku-1 quantity after inc to be "2", got "${item1QtyNew}"`);
  }

  const cartCountAfterInc = await page.locator('[data-testid="cart-count"]').innerText();
  console.log("Cart count after inc:", cartCountAfterInc);
  if (cartCountAfterInc !== "4") {
    throw new Error(`Expected cart count after inc to be "4", got "${cartCountAfterInc}"`);
  }

  const cartTotalAfterInc = await page.locator('[data-testid="cart-total"]').innerText();
  console.log("Cart total after inc:", cartTotalAfterInc);
  if (cartTotalAfterInc !== "$139.96") {
    throw new Error(`Expected cart total after inc to be "$139.96", got "${cartTotalAfterInc}"`);
  }

  // 7. Decrement sku-2
  console.log("Decrementing sku-2...");
  await page.locator('[data-testid="dec-sku-2"]').click();
  await page.waitForTimeout(500);

  const item2QtyNew = await page.locator('[data-testid="qty-sku-2"]').innerText();
  console.log("sku-2 quantity after dec:", item2QtyNew);
  if (item2QtyNew !== "1") {
    throw new Error(`Expected sku-2 quantity after dec to be "1", got "${item2QtyNew}"`);
  }

  const cartCountAfterDec = await page.locator('[data-testid="cart-count"]').innerText();
  console.log("Cart count after dec:", cartCountAfterDec);
  if (cartCountAfterDec !== "3") {
    throw new Error(`Expected cart count after dec to be "3", got "${cartCountAfterDec}"`);
  }

  const cartTotalAfterDec = await page.locator('[data-testid="cart-total"]').innerText();
  console.log("Cart total after dec:", cartTotalAfterDec);
  if (cartTotalAfterDec !== "$119.97") {
    throw new Error(`Expected cart total after dec to be "$119.97", got "${cartTotalAfterDec}"`);
  }

  // 8. Decrement sku-2 again to 0
  console.log("Decrementing sku-2 to 0...");
  await page.locator('[data-testid="dec-sku-2"]').click();
  await page.waitForTimeout(500);

  const item2QtyZero = await page.locator('[data-testid="qty-sku-2"]').innerText();
  console.log("sku-2 quantity at 0:", item2QtyZero);
  if (item2QtyZero !== "0") {
    throw new Error(`Expected sku-2 quantity to be "0", got "${item2QtyZero}"`);
  }

  // 9. Decrement sku-2 again (should not go below 0)
  console.log("Decrementing sku-2 again (should stay 0)...");
  await page.locator('[data-testid="dec-sku-2"]').click();
  await page.waitForTimeout(500);

  const item2QtyBelowZero = await page.locator('[data-testid="qty-sku-2"]').innerText();
  console.log("sku-2 quantity after extra dec:", item2QtyBelowZero);
  if (item2QtyBelowZero !== "0") {
    throw new Error(`Expected sku-2 quantity to stay "0", got "${item2QtyBelowZero}"`);
  }

  // 10. Add new item sku-3
  console.log("Adding new item sku-3...");
  await page.locator('[data-testid="add-item"]').click();
  await page.waitForTimeout(500);

  const item3Exists = await page.locator('[data-testid="item-sku-3"]').isVisible();
  console.log("sku-3 row is visible:", item3Exists);
  if (!item3Exists) {
    throw new Error("Expected sku-3 row to be visible after add-item click");
  }

  const item3Qty = await page.locator('[data-testid="qty-sku-3"]').innerText();
  console.log("sku-3 quantity:", item3Qty);
  if (item3Qty !== "1") {
    throw new Error(`Expected sku-3 quantity to be "1", got "${item3Qty}"`);
  }

  const cartCountAfterAdd = await page.locator('[data-testid="cart-count"]').innerText();
  console.log("Cart count after add:", cartCountAfterAdd);
  // Keyboard: 2 (qty) * 49.99 = 99.98
  // Mouse: 0 (qty) * 19.99 = 0
  // Cable: 1 (qty) * 9.99 = 9.99
  // Total Qty: 3
  // Total Price: 99.98 + 9.99 = 109.97
  if (cartCountAfterAdd !== "3") {
    throw new Error(`Expected cart count after add to be "3", got "${cartCountAfterAdd}"`);
  }

  const cartTotalAfterAdd = await page.locator('[data-testid="cart-total"]').innerText();
  console.log("Cart total after add:", cartTotalAfterAdd);
  if (cartTotalAfterAdd !== "$109.97") {
    throw new Error(`Expected cart total after add to be "$109.97", got "${cartTotalAfterAdd}"`);
  }

  // 11. Click add-item again (should not duplicate or change quantity if already exists)
  console.log("Clicking add-item again (should not duplicate)...");
  await page.locator('[data-testid="add-item"]').click();
  await page.waitForTimeout(500);

  const item3QtyAgain = await page.locator('[data-testid="qty-sku-3"]').innerText();
  console.log("sku-3 quantity after duplicate add:", item3QtyAgain);
  if (item3QtyAgain !== "1") {
    throw new Error(`Expected sku-3 quantity to stay "1", got "${item3QtyAgain}"`);
  }

  const cartCountAfterDuplicate = await page.locator('[data-testid="cart-count"]').innerText();
  if (cartCountAfterDuplicate !== "3") {
    throw new Error(`Expected cart count after duplicate add to stay "3", got "${cartCountAfterDuplicate}"`);
  }

  console.log("ALL E2E TESTS PASSED SUCCESSFULLY!");
  await browser.close();
}

run().catch((err) => {
  console.error("Test failed:", err);
  process.exit(1);
});
